const PREPAID_SUPPLIER_ALIASES=['IHERBS','IHERB','PHD','PHD ONLINE','TIGER NUTRITION','EHP','EHP LABS','AMAZON','INNOVATIVE','INNOVATIVE NUTRITION','SWITCH','SWITCH NUTRITION','LEGIT','LEGIT SUPPS','LEGIT SUPPS PTY LTD','MUSCLE & STRENGTH','MUSCLE AND STRENGTH','INB4','LVLUP','LVL UP','LVLUP HEALTH','LVL UP HEALTH'];
function supplierKey(name){return String(name||'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim()}
function isPrepaidSupplier(name){const key=supplierKey(name);return PREPAID_SUPPLIER_ALIASES.some(alias=>{const a=supplierKey(alias);return key===a||key.startsWith(a+' ')||key.includes(' '+a+' ')})}
function applySupplierPaymentDefaults(row){if(/^SUPPS247/i.test(String(row.supplier||''))||String(row.supplier||'')==='-')row.paymentStatus='Internal transfer';else if(isPrepaidSupplier(row.supplier)&&['','Unconfirmed','Unpaid'].includes(row.paymentStatus||''))row.paymentStatus='Prepaid';return row}
const SUPPLIER_PAYMENT_TERMS=[
  {days:45,aliases:['GLOBAL NUTRITION','GLOBAL','PRIMABOLICS']},
  {days:30,aliases:['GLANBIA','IOVATE','INTERNATIONAL PROTEIN','ATP']},
  {days:7,aliases:['DYNAMIC DISTRIBUTION','DYNAMIC']},
  {days:15,aliases:['RAPID SUPPLEMENTS','RAPID']}
];
const OUTSTANDING_TERM_STATUSES=new Set(['Due','Unpaid','Unconfirmed']);
function supplierTermDays(name){const key=supplierKey(name);for(const term of SUPPLIER_PAYMENT_TERMS){if(term.aliases.some(alias=>{const a=supplierKey(alias);return key===a||key.startsWith(a+' ')||key.includes(' '+a+' ')}))return term.days}return 0}
function dueDateFromTerms(row){const days=supplierTermDays(row?.supplier);if(!days||!OUTSTANDING_TERM_STATUSES.has(String(row?.paymentStatus||'')))return row?.dueDate||'';const base=parseDateLoose(row?.receivedDate||'');if(!base)return row?.dueDate||'';const calculated=dateKey(addDays(new Date(base+'T00:00:00'),days));const today=dateKey(new Date());return calculated<today?today:calculated}
function applySupplierDueDate(row){const due=dueDateFromTerms(row);if(due)row.dueDate=due;return row}
