let state=structuredClone(DEFAULT),revision=0,currentUser=null,currentWeek=startOfWeek(new Date()),payWeek=startOfWeek(addDays(new Date(),-7)),saving=false,queued=false,channel=null;const selectedAccountIds=new Set();
const $=id=>document.getElementById(id); const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(n||0));
function startOfWeek(d){d=new Date(d);d.setHours(0,0,0,0);const day=d.getDay();d.setDate(d.getDate()-((day+6)%7));return d}
function dateKey(d){const x=new Date(d);const y=x.getFullYear(),m=String(x.getMonth()+1).padStart(2,'0'),day=String(x.getDate()).padStart(2,'0');return `${y}-${m}-${day}`} function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function weekEnd(w){return addDays(w,6)}
function effectiveShiftDate(s){return s?.date||''}
function inWeek(dateOrShift,w){const key=typeof dateOrShift==='object'?effectiveShiftDate(dateOrShift):dateOrShift;const t=new Date(key+'T00:00:00');return t>=startOfWeek(w)&&t<=weekEnd(startOfWeek(w))}
function weekText(w){return `${addDays(w,0).toLocaleDateString('en-AU',{day:'numeric',month:'short'})} – ${weekEnd(w).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})}`}
function hours(s){let [sh,sm]=s.start.split(':').map(Number),[eh,em]=s.end.split(':').map(Number);let mins=eh*60+em-(sh*60+sm);if(mins<0)mins+=1440;return Math.max(0,mins/60)}
function storeDetail(name){return STORE_DETAILS[name]||null}
function storeHoursFor(name,date){const detail=storeDetail(name);if(!detail||!date)return null;const jsDay=new Date(date+'T00:00:00').getDay();const mondayIndex=(jsDay+6)%7;return detail.hours[mondayIndex]}
function formatTime(t){const [h,m]=t.split(':').map(Number);return new Date(2000,0,1,h,m).toLocaleTimeString('en-AU',{hour:'numeric',minute:'2-digit'})}
function applyStoreHours(){const h=storeHoursFor($('shiftOutlet').value,$('shiftDate').value);if(!h)return;$('shiftStart').value=h[0];$('shiftEnd').value=h[1];$('shiftType').value='Full day';$('shiftBreak').value=0;updateStoreHoursHint()}
function updateStoreHoursHint(){const detail=storeDetail($('shiftOutlet').value),h=storeHoursFor($('shiftOutlet').value,$('shiftDate').value);if(!detail||!h){$('storeHoursHint').textContent='';return}$('storeHoursHint').textContent=`Store hours: ${formatTime(h[0])} – ${formatTime(h[1])} · ${detail.address}`}
function outsideStoreHours(row){const h=storeHoursFor(row.location,row.date);return !!h&&(row.start<h[0]||row.end>h[1])}
function canonicalInvoiceNumber(value){let s=String(value||'').trim().toUpperCase();s=s.replace(/^(ORDER\s*#?|INVOICE\s*[-#:]?\s*|INV\s*[-#:]?\s*)/,'');return s.replace(/[^A-Z0-9]/g,'')}
function canonicalOutletKey(value){let s=String(value||'').trim().toUpperCase().replace(/SUPPS247/g,'').replace(/\(HEAD OFFICE\)/g,'').replace(/\(CHAPEL STREET\)/g,'');return s.replace(/[^A-Z0-9]/g,'')}
function accountKey(a){return `${canonicalInvoiceNumber(a.invoiceNumber)}|${supplierKey(a.supplier).replace(/[^A-Z0-9]/g,'')}|${canonicalOutletKey(a.outlet)}`}
const PAYMENT_STATUS_RANK={Paid:100,Prepaid:90,'Internal transfer':90,'No payment required':90,'Credit received':85,'Part paid':70,Scheduled:60,Due:50,Unpaid:40,Unconfirmed:30,Disputed:20};
function mergeAccountRows(base,row){const merged={...(base||{}),...(row||{})};if(!row?.dueDate&&base?.dueDate)merged.dueDate=base.dueDate;if(!row?.receivedDate&&base?.receivedDate)merged.receivedDate=base.receivedDate;if(!Number(row?.quantity||0)&&Number(base?.quantity||0))merged.quantity=base.quantity;if(!Number(row?.amount||0)&&Number(base?.amount||0))merged.amount=base.amount;const bs=String(base?.paymentStatus||''),rs=String(row?.paymentStatus||'');if((PAYMENT_STATUS_RANK[bs]||0)>(PAYMENT_STATUS_RANK[rs]||0))merged.paymentStatus=bs;if(!merged.paidDate&&base?.paidDate)merged.paidDate=base.paidDate;if(!merged.receiptNumber&&base?.receiptNumber)merged.receiptNumber=base.receiptNumber;if(!merged.paymentReference&&base?.paymentReference)merged.paymentReference=base.paymentReference;if(!merged.notes&&base?.notes)merged.notes=base.notes;return applySupplierDueDate(applySupplierPaymentDefaults(merged))}
function accountFingerprint(a){return `${supplierKey(a.supplier).replace(/[^A-Z0-9]/g,'')}|${canonicalOutletKey(a.outlet)}|${parseDateLoose(a.receivedDate||'')}|${Number(a.quantity||0)}|${Number(a.amount||0).toFixed(2)}`}
function normalize(raw){const employees=(raw.employees||NAMES).map(e=>{const emp=typeof e==='string'?baseEmployee(e):{...baseEmployee(e.name),...e};return{...emp,satMultiplier:1,sunMultiplier:1}});const deletedAccountKeys=[...new Set(Array.isArray(raw.deletedAccountKeys)?raw.deletedAccountKeys:[])];const deletedAccountIds=[...new Set(Array.isArray(raw.deletedAccountIds)?raw.deletedAccountIds:[])];const suppressedSeedAccountIds=[...new Set(Array.isArray(raw.suppressedSeedAccountIds)?raw.suppressedSeedAccountIds:[])];const deletedSet=new Set(deletedAccountKeys),deletedIds=new Set(deletedAccountIds),suppressedSeeds=new Set(suppressedSeedAccountIds);const byKey=new Map();for(const a of IMPORTED_RECEIVING){if(deletedIds.has(a.id)||suppressedSeeds.has(a.id))continue;const row=applySupplierDueDate(applySupplierPaymentDefaults({...a})),k=accountKey(row);if(deletedSet.has(k))continue;byKey.set(k,byKey.has(k)?mergeAccountRows(byKey.get(k),row):row)}for(const s of (Array.isArray(raw.accounts)?raw.accounts:[])){if(deletedIds.has(s.id))continue;const k=accountKey(s);if(deletedSet.has(k))continue;const base=byKey.get(k)||{};byKey.set(k,mergeAccountRows(base,s))}let accounts=[...byKey.values()];const correctedByFingerprint=new Map();for(const a of accounts){const fp=accountFingerprint(a),isCorrected=String(a.source||'').toLowerCase().includes('manual / corrected');if(!correctedByFingerprint.has(fp)){correctedByFingerprint.set(fp,a);continue}const prev=correctedByFingerprint.get(fp),prevCorrected=String(prev.source||'').toLowerCase().includes('manual / corrected');if(isCorrected&&!prevCorrected)correctedByFingerprint.set(fp,a)}accounts=[...correctedByFingerprint.values()];return{employees,locations:raw.locations?.length?raw.locations:LOCATIONS,shifts:raw.shifts||[],accounts,deletedAccountKeys,deletedAccountIds,suppressedSeedAccountIds,stockProducts:(()=>{const by=new Map();for(const p of POINT_COOK_APRIL_PRODUCTS)by.set(String(p.sku||p.name).toLowerCase(),{...p});for(const p of (Array.isArray(raw.stockProducts)?raw.stockProducts:[]))by.set(String(p.sku||p.name).toLowerCase(),{...(by.get(String(p.sku||p.name).toLowerCase())||{}),...p});return [...by.values()]})(),stockMovements:(()=>{const all=[...POINT_COOK_APRIL_PURCHASES,...(Array.isArray(raw.stockMovements)?raw.stockMovements:[])],seen=new Set(),out=[];for(const m of all){const k=[m.type,m.month||m.date,String(m.purchaseOrder||''),String(m.sku||m.name).toLowerCase(),Number(m.quantity||0).toFixed(3),Number(m.total||0).toFixed(2)].join('|');if(seen.has(k))continue;seen.add(k);out.push(m)}return out})()}}
function setStatus(ok,text){$('connectionStatus').className=`status ${ok?'online':'offline'}`;$('connectionStatus').textContent=text}
function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),2500)}
async function load(){const {data,error}=await db.from('roster_state').select('*').eq('id',1).single();if(error)throw error;state=normalize(data.state||{});revision=Number(data.revision||0)}
async function save(){
  if(saving){queued=true;return true}
  saving=true;setStatus(true,'Saving…');
  let ok=false;
  try{
    // Remove undefined/browser-only values before sending the state to Postgres JSONB.
    const cleanState=JSON.parse(JSON.stringify(state));
    if(!currentUser){
      const {data:sessionData}=await db.auth.getSession();
      if(!sessionData?.session){
        const refreshed=await db.auth.refreshSession();
        if(refreshed.error||!refreshed.data?.session)throw new Error('Your login session expired. Please sign out and sign in again.');
      }
    }
    let result=await db.rpc('save_roster_state',{p_state:cleanState,p_base_revision:revision,p_updated_by:currentUser?.email||'Admin'});
    // Retry once when the access token expired between loading and saving.
    if(result.error&&/jwt|token|auth/i.test(result.error.message||'')){
      const refreshed=await db.auth.refreshSession();
      if(!refreshed.error)result=await db.rpc('save_roster_state',{p_state:cleanState,p_base_revision:revision,p_updated_by:currentUser?.email||'Admin'});
    }
    if(result.error)throw result.error;
    const row=Array.isArray(result.data)?result.data[0]:result.data;
    if(row?.conflict){
      state=normalize(row.state||{});revision=Number(row.revision||0);
      setStatus(false,'Reloaded latest data');
      toast('Another user saved changes first. Latest cloud data was reloaded; please repeat your last edit.');
      render();
      return false;
    }
    revision=Number(row?.revision||revision+1);
    state=cleanState;
    setStatus(true,'Cloud synced');ok=true;
    return true;
  }catch(e){
    console.error('Supabase save failed',e);
    const message=e?.message||e?.details||'Unknown cloud error';
    setStatus(false,'Save failed');
    toast(`Save failed: ${message}`);
    return false;
  }finally{
    saving=false;
    if(queued){queued=false;setTimeout(()=>save(),100)}
  }
}
function subscribe(){if(channel)db.removeChannel(channel);channel=db.channel('supps247-admin').on('postgres_changes',{event:'UPDATE',schema:'public',table:'roster_state',filter:'id=eq.1'},p=>{if(Number(p.new.revision)>revision){revision=Number(p.new.revision);state=normalize(p.new.state||{});render();toast('Updated from another device')}}).subscribe()}
function employee(name){return state.employees.find(e=>e.name===name)||baseEmployee(name)}
const STORE_PAYROLL_RATE=28;
function storeHoursLength(pair){if(!pair)return 0;const [sh,sm]=pair[0].split(':').map(Number),[eh,em]=pair[1].split(':').map(Number);return Math.max(0,(eh*60+em-(sh*60+sm))/60)}
function payrollEmployeeForOutlet(outlet,index){return state.employees.find(e=>e.homeOutlet===outlet)||state.employees[index%Math.max(1,state.employees.length)]||baseEmployee('Store staff')}
function payrollRows(week,outlet='All outlets'){const outlets=(outlet==='All outlets'?state.locations:[outlet]).filter(name=>STORE_DETAILS[name]);return outlets.map((location,index)=>{const detail=STORE_DETAILS[location],emp=payrollEmployeeForOutlet(location,index);let weekday=0,sat=0,sun=0;detail.hours.forEach((pair,dayIndex)=>{const h=storeHoursLength(pair);if(dayIndex===5)sat+=h;else if(dayIndex===6)sun+=h;else weekday+=h});const gross=(weekday+sat+sun)*STORE_PAYROLL_RATE;return{emp:{...emp,baseRate:STORE_PAYROLL_RATE},location,weekday,sat,sun,gross,allowance:0,total:gross}})}

function weeklyCellShift(employeeName,dayIndex,outlet){const date=dateKey(addDays(currentWeek,dayIndex));return state.shifts.find(s=>s.employee===employeeName&&s.location===outlet&&effectiveShiftDate(s)===date)||null}
function weeklyPresetFor(s){if(!s)return'Off';if(s.shiftType&&['Full day','Half AM','Half PM'].includes(s.shiftType))return s.shiftType;return'Custom'}
function weeklyCellHtml(emp,dayIndex,outlet){const s=weeklyCellShift(emp.name,dayIndex,outlet),preset=weeklyPresetFor(s),date=dateKey(addDays(currentWeek,dayIndex)),h=storeHoursFor(outlet,date)||['09:00','17:00'];let start=s?.start||h[0],end=s?.end||h[1];return `<td class="weekly-cell ${preset==='Off'?'weekly-off':''}" data-employee="${esc(emp.name)}" data-day="${dayIndex}"><select class="weekly-preset"><option${preset==='Off'?' selected':''}>Off</option><option${preset==='Full day'?' selected':''}>Full day</option><option${preset==='Half AM'?' selected':''}>Half AM</option><option${preset==='Half PM'?' selected':''}>Half PM</option><option${preset==='Custom'?' selected':''}>Custom</option></select><div class="weekly-time-row"><input class="weekly-start" type="time" value="${start}"><input class="weekly-end" type="time" value="${end}"></div><input class="weekly-break" type="hidden" value="0"><span class="weekly-hours">${preset==='Off'?'Off':formatTime(start)+'–'+formatTime(end)}</span></td>`}
