function applyWeeklyPreset(cell){const preset=cell.querySelector('.weekly-preset').value,outlet=$('weeklyRosterOutlet').value,date=dateKey(addDays(currentWeek,Number(cell.dataset.day))),h=storeHoursFor(outlet,date)||['09:00','17:00'],start=cell.querySelector('.weekly-start'),end=cell.querySelector('.weekly-end'),br=cell.querySelector('.weekly-break');cell.classList.toggle('weekly-off',preset==='Off');if(preset==='Full day'){start.value=h[0];end.value=h[1];br.value=0}else if(preset==='Half AM'){start.value=h[0];const [oh,om]=h[0].split(':').map(Number);start.value=h[0];end.value=`${String(Math.min(23,oh+4)).padStart(2,'0')}:${String(om).padStart(2,'0')}`;br.value=0}else if(preset==='Half PM'){const [eh,em]=h[1].split(':').map(Number);start.value=`${String(Math.max(0,eh-4)).padStart(2,'0')}:${String(em).padStart(2,'0')}`;end.value=h[1];br.value=0}updateWeeklyCellLabel(cell)}
