async function applyBulkPayments(){const ids=[...selectedAccountIds];if(!ids.length){toast('Select at least one invoice');return}const status=$('bulkPaymentStatus').value,date=$('bulkPaidDate').value,receipt=$('bulkReceiptNumber').value.trim();for(const a of state.accounts||[]){if(!selectedAccountIds.has(a.id))continue;if(status)a.paymentStatus=status;if(date){a.paidDate=date;if(!status)a.paymentStatus='Paid'}if(receipt){a.receiptNumber=receipt;a.paymentReference=receipt}if(status==='Paid'&&!a.paidDate)a.paidDate=dateKey(new Date());if(['Unconfirmed','Unpaid','Due','Scheduled','Disputed'].includes(status))a.paidDate=''}if(await save()){clearAccountSelection();$('bulkPaymentStatus').value='';$('bulkPaidDate').value='';$('bulkReceiptNumber').value='';toast(`${ids.length} payments updated`)}}
