function normaliseInvoiceDate(value){
  if(!value)return '';
  const s=String(value).trim().replace(/,/g,'');
  let m=s.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})\b/);
  if(m){let y=Number(m[3]);if(y<100)y+=2000;return `${y}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`}
  m=s.match(/\b(\d{1,2})\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{2,4})\b/i);
  if(m){const months=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];let y=Number(m[3]);if(y<100)y+=2000;return `${y}-${String(months.indexOf(m[2].slice(0,3).toLowerCase())+1).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`}
  return '';
}
function firstMatch(text,patterns){for(const p of patterns){const m=text.match(p);if(m&&m[1])return m[1].trim()}return ''}
function extractAmount(text){
  const patterns=[
    /\btotal\s+inc\.?\s*gst\s*[:$ ]*\$?\s*([0-9][0-9,]*\.\d{2})/ig,
    /\btotal\s+(?:incl\.?|including)\s*gst\s*[:$ ]*\$?\s*([0-9][0-9,]*\.\d{2})/ig,
    /\b(?:invoice\s+total|amount\s+due|balance\s+due|total\s+due|grand\s+total|total\s+aud)\s*[:$ ]*\$?\s*([0-9][0-9,]*\.\d{2})/ig,
    /\btotal\s*[:$ ]+\$?\s*([0-9][0-9,]*\.\d{2})/ig
  ];
  for(const re of patterns){let found=[],m;while((m=re.exec(text)))found.push(Number(m[1].replace(/,/g,'')));if(found.length)return found[found.length-1]}
  return 0;
}
function extractInvoiceNumber(text){
  return firstMatch(text,[
    /\btax\s+invoice\s+no\.?\s*[:#-]?\s*([A-Z0-9][A-Z0-9\-\/]{2,30})\b/i,
    /\binvoice\s+(?:number|no\.?)\s*[:#-]?\s*([A-Z0-9][A-Z0-9\-\/]{2,30})\b/i,
    /\binvoice\s*#\s*([A-Z0-9][A-Z0-9\-\/]{2,30})\b/i,
    /\binv\s*#\s*([A-Z0-9][A-Z0-9\-\/]{2,30})\b/i
  ]);
}
function guessSupplier(text,fileName){
  const known=[...accountSuppliers(),...PREPAID_SUPPLIER_ALIASES,'GLOBAL NUTRITION','NUTRITION SYSTEMS','ATP','GLANBIA','IOVATE','PRIMABOLICS','DYNAMIC DISTRIBUTION','RAPID SUPPLEMENTS','NEXT GENERATION','INTERNATIONAL PROTEIN','FIBRE BOOST','DR. HYDRATE','AXE & SLEDGE','PICKLE JUICE','ZAYN'];
  const upper=text.toUpperCase();const match=known.sort((a,b)=>b.length-a.length).find(n=>upper.includes(String(n).toUpperCase()));
  if(match){
    const existing=accountSuppliers().find(s=>normaliseKey(s)===normaliseKey(match));
    return existing||String(match).replace(/\b\w/g,c=>c.toUpperCase());
  }
  return '';
}
function guessOutlet(text){
  const upper=text.toUpperCase();
  const aliases=[['Springvale (Head Office)',['SUPPS 247 SPRINGVALE','SUPPS247 SPRINGVALE','SPRINGVALE']],['South Yarra (Chapel Street)',['SUPPS 247 SOUTH YARRA','SUPPS247 SOUTH YARRA','SOUTH YARRA','CHAPEL STREET']],['Chirnside Park',['SUPPS 247 CHIRNSIDE','SUPPS247 CHIRNSIDE','CHIRNSIDE']],...LOCATIONS.filter(x=>!['Springvale (Head Office)','South Yarra (Chapel Street)','Chirnside Park'].includes(x)).map(x=>[x,[`SUPPS 247 ${x.toUpperCase()}`,`SUPPS247 ${x.toUpperCase()}`,x.toUpperCase()]])];
  for(const [outlet,names] of aliases)if(names.some(n=>upper.includes(n)))return outlet;
  return '';
}
function extractInvoiceQuantity(text){
  const lineMatches=[...text.matchAll(/\b(\d+(?:\.\d+)?)\s+(?:EACH|EA|UNIT|UNITS|PCS|PC)\b/ig)];
  if(lineMatches.length===1)return Number(lineMatches[0][1])||0;
  return 0;
}
async function readPdfText(file){
  const pdfjsLib=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');
  pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';
  const data=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjsLib.getDocument({data}).promise;let text='';
  for(let i=1;i<=Math.min(pdf.numPages,12);i++){const page=await pdf.getPage(i);const content=await page.getTextContent();text+='\n'+content.items.map(x=>x.str).join(' ')}
  return text.replace(/\s+/g,' ').trim();
}
async function importSupplierPdf(file){
  openInvoice();$('invoiceDialogTitle').textContent='Review supplier PDF';$('pdfImportStatus').classList.remove('hidden');$('pdfImportStatus').textContent='Reading PDF…';$('invoiceSourceFile').value=file.name;
  try{
    const text=await readPdfText(file);
    if(!text||text.length<30)throw new Error('No selectable text was found. This may be a scanned image PDF.');
    const invoiceNumber=extractInvoiceNumber(text);
    const invoiceDateRaw=firstMatch(text,[/\btax\s+invoice\s+date\s*:?[ ]*([0-9]{1,2}[\/.\-][0-9]{1,2}[\/.\-][0-9]{2,4})/i,/\b(?:invoice\s+date|date\s+issued|issued\s+date)\s*:?[ ]*([0-9]{1,2}[\/.\-][0-9]{1,2}[\/.\-][0-9]{2,4})/i,/\b(?:invoice\s+date|date\s+issued)\s*:?[ ]*([0-9]{1,2}\s+[A-Za-z]{3,9}\s+[0-9]{2,4})/i]);
    const dueDateRaw=firstMatch(text,[/\bdue\s+date\s*:?[ ]*([0-9]{1,2}[\/.\-][0-9]{1,2}[\/.\-][0-9]{2,4})/i,/\bpayment\s+due\s*:?[ ]*([0-9]{1,2}[\/.\-][0-9]{1,2}[\/.\-][0-9]{2,4})/i,/\b(?:due\s+date|payment\s+due)\s*:?[ ]*([0-9]{1,2}\s+[A-Za-z]{3,9}\s+[0-9]{2,4})/i]);
    const supplier=guessSupplier(text,file.name),outlet=guessOutlet(text),amount=extractAmount(text),quantity=extractInvoiceQuantity(text);
    $('invoiceNumber').value=invoiceNumber||'';
    $('invoiceSupplier').value=supplier;
    $('invoiceOutlet').value=outlet;
    $('invoiceReceivedDate').value=normaliseInvoiceDate(invoiceDateRaw);
    $('invoiceDueDate').value=normaliseInvoiceDate(dueDateRaw);
    $('invoiceQuantity').value=quantity||0;
    $('invoiceAmount').value=amount||0;
    $('invoicePaymentStatus').value=applySupplierPaymentDefaults({supplier,paymentStatus:'Unconfirmed'}).paymentStatus;
    $('invoiceNotes').value=`Imported from supplier PDF: ${file.name}`;
    const missing=[];if(!invoiceNumber)missing.push('invoice number');if(!supplier)missing.push('supplier');if(!outlet)missing.push('outlet');if(!normaliseInvoiceDate(invoiceDateRaw))missing.push('invoice date');if(!normaliseInvoiceDate(dueDateRaw))missing.push('due date');if(!amount)missing.push('total amount');
    const duplicate=invoiceNumber&&(state.accounts||[]).find(a=>normaliseKey(a.invoiceNumber)===normaliseKey(invoiceNumber)&&(!supplier||normaliseKey(a.supplier)===normaliseKey(supplier)));
    $('pdfImportStatus').innerHTML=`<strong>PDF read.</strong> Review every field before saving.${missing.length?`<br><span class="warning-text">Not confidently detected: ${esc(missing.join(', '))}.</span>`:''}${duplicate?`<br><span class="warning-text">Possible duplicate: this invoice number already exists in Accounts.</span>`:''}<br><small>${esc(file.name)} · ${text.length.toLocaleString()} characters extracted</small>`;
  }catch(err){console.error(err);$('pdfImportStatus').innerHTML=`Could not read this PDF automatically: ${esc(err.message)}<br><small>You can still enter the details manually, or upload a text-based PDF.</small>`;toast('PDF needs manual review')}
}

function parseReceivingText(txt){const lines=txt.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),out=[];let i=lines[0]?.startsWith('Order number')?1:0;while(i<lines.length){const invoiceNumber=lines[i++];if(i+1>=lines.length)break;let meta=lines[i++].split('\t').map(x=>x.trim()).filter(Boolean),vals=lines[i++].split('\t').map(x=>x.trim()).filter(Boolean),dueDate='';if(meta[0]?.startsWith('Due:'))dueDate=meta.shift().slice(4).trim();if(meta.length<3||vals.length<3)continue;const [supplier,rawOutlet,receivingStatus]=meta,[receivedDate,qtyRaw,amountRaw]=vals;if(receivingStatus!=='Received')continue;const outlet=rawOutlet==='Supps247 Chirnside Park'?'Chirnside Park':rawOutlet==='South Yarra'?'South Yarra (Chapel Street)':rawOutlet==='Springvale'?'Springvale (Head Office)':rawOutlet;out.push(applySupplierDueDate({id:crypto.randomUUID(),invoiceNumber,supplier,outlet,receivedDate,dueDate,quantity:Number(qtyRaw.replace(/[^0-9]/g,''))||0,amount:Number(amountRaw.replace(/,/g,'').replace(/[^0-9.]/g,''))||0,receivingStatus:'Received',paymentStatus:applySupplierPaymentDefaults({supplier,paymentStatus:'Unconfirmed'}).paymentStatus,paidDate:'',paymentReference:'',notes:'Imported from receiving file',source:'Receiving import'}))}return out}

let statementImportRows=[];
let statementImportFileName='';
function normaliseKey(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function cleanMoney(v){if(typeof v==='number')return v;const n=Number(String(v||'').replace(/\(([^)]+)\)/,'-$1').replace(/,/g,'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:0}
function dateFromExcelValue(v){if(v instanceof Date&&!isNaN(v))return dateKey(v);if(typeof v==='number'&&v>20000){const d=new Date(Math.round((v-25569)*86400*1000));return dateKey(d)}return parseDateLoose(String(v||''))}
function firstValue(row,names){for(const [k,v] of Object.entries(row||{})){const nk=normaliseKey(k);if(names.some(n=>nk.includes(n)))return v}return ''}
function rowsFromSheetObjects(rows){return rows.map((r,i)=>({
  id:`statement-${i}-${crypto.randomUUID()}`,
  invoiceNumber:String(firstValue(r,['invoicenumber','invoice','invno','documentnumber','docno','reference','number'])||'').trim(),
  invoiceDate:dateFromExcelValue(firstValue(r,['invoicedate','documentdate','docdate','date'])),
  dueDate:dateFromExcelValue(firstValue(r,['duedate','paymentdue','due'])),
  amount:cleanMoney(firstValue(r,['balance','outstanding','amountdue','totalamount','invoicetotal','total','amount'])),
  description:String(firstValue(r,['description','details','memo'])||'').trim()
})).filter(r=>r.invoiceNumber&&Math.abs(r.amount)>0)}
async function loadSheetJs(){if(window.XLSX)return window.XLSX;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';s.onload=resolve;s.onerror=()=>reject(new Error('Could not load Excel reader'));document.head.appendChild(s)});return window.XLSX}
async function parseStatementSpreadsheet(file){const XLSX=await loadSheetJs();const data=await file.arrayBuffer();const wb=XLSX.read(data,{type:'array',cellDates:true});const all=[];for(const name of wb.SheetNames){const objects=XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:'',raw:true});all.push(...rowsFromSheetObjects(objects))}return all}
async function extractPdfText(file){const pdfjsLib=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const data=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjsLib.getDocument({data}).promise;let text='';for(let i=1;i<=Math.min(pdf.numPages,30);i++){const page=await pdf.getPage(i),content=await page.getTextContent();text+='\n'+content.items.map(x=>x.str).join(' ')}return text}
function parseStatementPdfText(text){const lines=String(text||'').split(/\n+/).map(x=>x.replace(/\s+/g,' ').trim()).filter(Boolean),rows=[];const dateRe=/(\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}|\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4}|[A-Za-z]{3,9}\s+\d{1,2},?\s+\d{2,4})/g;for(let i=0;i<lines.length;i++){const line=lines[i];const amounts=[...line.matchAll(/(?:\$\s*)?\(?-?\d[\d,]*\.\d{2}\)?/g)].map(m=>m[0]);if(!amounts.length)continue;const dates=[...line.matchAll(dateRe)].map(m=>m[0]);const tokens=line.split(' ');let inv=tokens.find(t=>/[A-Za-z]/.test(t)&&/\d/.test(t)&&t.length>=4)||tokens.find(t=>/^\d{4,}$/.test(t));if(!inv)continue;rows.push({id:`statement-pdf-${i}-${crypto.randomUUID()}`,invoiceNumber:inv.replace(/[,:;]$/,''),invoiceDate:dateFromExcelValue(dates[0]||''),dueDate:dateFromExcelValue(dates[1]||''),amount:cleanMoney(amounts[amounts.length-1]),description:line})}const seen=new Set();return rows.filter(r=>{const k=normaliseKey(r.invoiceNumber)+'|'+r.amount;if(seen.has(k))return false;seen.add(k);return r.amount!==0})}
function statementSupplierGuess(name){const base=String(name||'').replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ');const suppliers=[...new Set((state.accounts||[]).map(a=>a.supplier).filter(Boolean))];return suppliers.find(s=>normaliseKey(base).includes(normaliseKey(s))||normaliseKey(s).includes(normaliseKey(base)))||''}
function reconcileStatementRows(){const supplier=$('statementSupplier').value.trim(),outlet=$('statementOutlet').value.trim();return statementImportRows.map(r=>{const exact=(state.accounts||[]).find(a=>normaliseKey(a.invoiceNumber)===normaliseKey(r.invoiceNumber)&&(!supplier||normaliseKey(a.supplier)===normaliseKey(supplier))&&(!outlet||normaliseKey(a.outlet)===normaliseKey(outlet)));let result='Missing',existing=null;if(exact){existing=exact;const amountDiff=Math.abs(Number(exact.amount||0)-Number(r.amount||0))>0.01;const dateDiff=!!(r.invoiceDate&&exact.receivedDate&&parseDateLoose(exact.receivedDate)!==r.invoiceDate);result=(amountDiff||dateDiff)?'Mismatch':'Matched'}return {...r,result,existing,selected:result==='Missing'}})}
function renderStatementPreview(){const rows=reconcileStatementRows();$('statementRowCount').textContent=rows.length;$('statementMatchedCount').textContent=rows.filter(r=>r.result==='Matched').length;$('statementMissingCount').textContent=rows.filter(r=>r.result==='Missing').length;$('statementMismatchCount').textContent=rows.filter(r=>r.result==='Mismatch').length;$('statementTotal').textContent=money(rows.reduce((s,r)=>s+Number(r.amount||0),0));$('statementMissingTotal').textContent=money(rows.filter(r=>r.result==='Missing'&&r.selected!==false).reduce((s,r)=>s+Number(r.amount||0),0));$('statementPreviewBody').innerHTML=rows.length?rows.map(r=>`<tr class="statement-${r.result.toLowerCase()}"><td>${r.result==='Missing'?`<input type="checkbox" class="statement-add-check" data-id="${r.id}" checked>`:''}</td><td><strong>${esc(r.invoiceNumber)}</strong></td><td>${esc(r.invoiceDate||'—')}</td><td>${esc(r.dueDate||'—')}</td><td>${money(r.amount)}</td><td><span class="pill">${r.result}</span>${r.result==='Mismatch'?`<small class="muted block">System: ${money(r.existing?.amount)} ${esc(r.existing?.receivedDate||'')}</small>`:''}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No invoice rows were detected. Try an Excel/CSV statement or add invoices manually.</td></tr>';document.querySelectorAll('.statement-add-check').forEach(c=>c.onchange=()=>{$('statementMissingTotal').textContent=money(rows.filter(r=>r.result==='Missing'&&document.querySelector(`.statement-add-check[data-id="${r.id}"]`)?.checked).reduce((s,r)=>s+Number(r.amount||0),0))})}
async function openSupplierStatement(file){statementImportFileName=file.name;$('statementFileLabel').textContent=file.name;$('statementSupplier').value=statementSupplierGuess(file.name);$('statementOutlet').value=$('accountsOutletFilter').value&&$('accountsOutletFilter').value!=='All outlets'?$('accountsOutletFilter').value:'';$('statementDate').value=dateKey(new Date());$('statementMessage').textContent='Reading statement…';$('statementDialog').showModal();try{if(/\.pdf$/i.test(file.name)){const text=await extractPdfText(file);statementImportRows=parseStatementPdfText(text)}else statementImportRows=await parseStatementSpreadsheet(file);$('statementMessage').textContent=statementImportRows.length?'Review the comparison below. Only selected missing invoices will be added.':'No invoice rows were detected. Check that the file has invoice number, date and amount columns.';renderStatementPreview()}catch(err){console.error(err);statementImportRows=[];$('statementMessage').textContent=`Could not read this statement: ${err.message}`;renderStatementPreview()}}
