// Reports module
function reportGroups(field){
  const map=new Map();
  for(const row of state.accounts||[]){
    const key=String(row[field]||'Unknown').trim()||'Unknown';
    if(!map.has(key))map.set(key,{name:key,count:0,total:0,outstanding:0});
    const g=map.get(key);g.count++;g.total+=Number(row.amount||0);if(isOutstanding(row))g.outstanding+=Number(row.amount||0);
  }
  return [...map.values()].sort((a,b)=>b.total-a.total);
}
function renderReports(){
  if(!$('supplierReportBody'))return;
  const accounts=state.accounts||[];
  const labour=payrollRows(currentWeek).reduce((sum,row)=>sum+Number(row.total||0),0);
  $('reportSupplierSpend').textContent=money(accounts.reduce((sum,row)=>sum+Number(row.amount||0),0));
  $('reportOutstanding').textContent=money(accounts.filter(isOutstanding).reduce((sum,row)=>sum+Number(row.amount||0),0));
  const today=dateKey(new Date());
  $('reportOverdueCount').textContent=accounts.filter(row=>isOutstanding(row)&&row.dueDate&&parseDateLoose(row.dueDate)<today).length;
  $('reportLabour').textContent=money(labour);
  const supplierRows=reportGroups('supplier');
  const outletRows=reportGroups('outlet');
  $('supplierReportBody').innerHTML=supplierRows.length?supplierRows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.count}</td><td>${money(r.total)}</td><td>${money(r.outstanding)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No account data.</td></tr>';
  $('outletReportBody').innerHTML=outletRows.length?outletRows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.count}</td><td>${money(r.total)}</td><td>${money(r.outstanding)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No account data.</td></tr>';
  const attention=accounts.filter(row=>isOutstanding(row)).sort((a,b)=>(parseDateLoose(a.dueDate)||'9999').localeCompare(parseDateLoose(b.dueDate)||'9999')).slice(0,100);
  $('attentionReportBody').innerHTML=attention.length?attention.map(a=>`<tr><td><strong>${esc(a.invoiceNumber||'')}</strong></td><td>${esc(a.supplier||'')}</td><td>${esc(a.outlet||'')}</td><td>${esc(a.dueDate||'—')}</td><td>${money(a.amount)}</td><td><span class="status-pill status-${String(a.paymentStatus||'unconfirmed').toLowerCase().replaceAll(' ','-')}">${esc(a.paymentStatus||'Unconfirmed')}</span></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No invoices require attention.</td></tr>';
}
function exportGroupedReport(field,fileName){
  const rows=reportGroups(field);
  csvDownload(fileName,[[field==='supplier'?'Supplier':'Outlet','Invoice count','Total spend','Outstanding'],...rows.map(r=>[r.name,r.count,r.total.toFixed(2),r.outstanding.toFixed(2)])]);
}
window.addEventListener('DOMContentLoaded',()=>{
  const supplierBtn=$('exportSupplierReportBtn'),outletBtn=$('exportOutletReportBtn');
  if(supplierBtn)supplierBtn.onclick=()=>exportGroupedReport('supplier',`supps247-supplier-report-${dateKey(new Date())}.csv`);
  if(outletBtn)outletBtn.onclick=()=>exportGroupedReport('outlet',`supps247-outlet-report-${dateKey(new Date())}.csv`);
});


// Point Cook sales, purchases and stock module
const POINT_COOK_OUTLET='Point Cook';
const STOCK_CATEGORIES=['Protein','Pre-Workout','Creatine','Aminos & Intra','Hydration & Electrolytes','Vitamins & Wellness','Weight Management','Snacks & Bars','Energy & RTD','Accessories','Other'];
function inferStockCategory(name,rawCategory=''){
  const raw=String(rawCategory||'').trim();
  if(raw)return raw;
  const n=String(name||'').toLowerCase();
  if(/whey|protein|isolate|casein|mass gainer|gainer|collagen/.test(n))return 'Protein';
  if(/pre[- ]?workout|preworkout|pump|stim/.test(n))return 'Pre-Workout';
  if(/creatine/.test(n))return 'Creatine';
  if(/bcaa|eaa|amino|intra/.test(n))return 'Aminos & Intra';
  if(/electrolyte|hydration|hydrate/.test(n))return 'Hydration & Electrolytes';
  if(/vitamin|mineral|magnesium|zinc|greens|omega|fish oil|wellness|multivitamin/.test(n))return 'Vitamins & Wellness';
  if(/fat burn|thermo|weight loss|carnitine/.test(n))return 'Weight Management';
  if(/bar|snack|cookie|chips|brownie|spread/.test(n))return 'Snacks & Bars';
  if(/energy drink|rtd|ready to drink|can\b|shot\b/.test(n))return 'Energy & RTD';
  if(/shaker|bottle|bag|strap|belt|accessor/.test(n))return 'Accessories';
  return 'Other';
}
function stockSku(row){return String(row?.sku||row?.barcode||row?.productCode||row?.name||'').trim()}
function ensureStockProduct(seed){
  const sku=stockSku(seed),name=String(seed.name||seed.product||sku||'Unknown product').trim();
  if(!sku&&!name)return null;
  let p=(state.stockProducts||[]).find(x=>String(x.sku||'').toLowerCase()===sku.toLowerCase())||
        (state.stockProducts||[]).find(x=>String(x.name||'').toLowerCase()===name.toLowerCase());
  if(!p){p={id:crypto.randomUUID(),sku:sku||name,name,brand:String(seed.brand||''),category:inferStockCategory(name,seed.category),onHand:Number(seed.onHand||0),reorderPoint:Number(seed.reorderPoint||3),cost:Number(seed.cost||0),retailPrice:Number(seed.retailPrice||0),lastUpdated:dateKey(new Date())};state.stockProducts.push(p)}
  else{
    if(seed.name)p.name=name;if(seed.brand)p.brand=String(seed.brand);if(seed.category)p.category=inferStockCategory(name,seed.category);
    if(seed.onHand!==undefined&&seed.onHand!==''&&!Number.isNaN(Number(seed.onHand)))p.onHand=Number(seed.onHand);
    if(seed.reorderPoint!==undefined&&seed.reorderPoint!==''&&!Number.isNaN(Number(seed.reorderPoint)))p.reorderPoint=Number(seed.reorderPoint);
    if(seed.cost!==undefined&&seed.cost!==''&&!Number.isNaN(Number(seed.cost)))p.cost=Number(seed.cost);
    if(seed.retailPrice!==undefined&&seed.retailPrice!==''&&!Number.isNaN(Number(seed.retailPrice)))p.retailPrice=Number(seed.retailPrice);
    p.lastUpdated=dateKey(new Date());
  }
  return p;
}
function firstStockValue(row,names){for(const [k,v] of Object.entries(row||{})){const nk=normaliseKey(k);if(names.some(n=>nk===n||nk.includes(n)))return v}return ''}
function stockNumber(v){const n=Number(String(v??'').replace(/,/g,'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:0}
function stockDate(v){return dateFromExcelValue(v)||dateKey(new Date())}
async function readStockFileRows(file){
  const XLSX=await loadSheetJs(),data=await file.arrayBuffer(),wb=XLSX.read(data,{type:'array',cellDates:true}),rows=[];
  for(const name of wb.SheetNames)rows.push(...XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:'',raw:true}));
  return rows;
}
function movementKey(m){return [m.type,parseDateLoose(m.date)||m.date,normaliseKey(m.sku||m.name),Number(m.quantity||0).toFixed(3),Number(m.total||0).toFixed(2)].join('|')}
function addStockMovement(m){state.stockMovements=state.stockMovements||[];const k=movementKey(m);if(state.stockMovements.some(x=>movementKey(x)===k))return false;state.stockMovements.push({...m,id:m.id||crypto.randomUUID(),outlet:POINT_COOK_OUTLET});return true}
async function importPointCookProducts(file){
  const rows=await readStockFileRows(file);let changed=0;
  for(const r of rows){
    const outlet=String(firstStockValue(r,['outlet','location','store'])||'');if(outlet&&!/point\s*cook/i.test(outlet))continue;
    const name=String(firstStockValue(r,['productname','product','name','description'])||'').trim();const sku=String(firstStockValue(r,['sku','productcode','code','barcode'])||'').trim();if(!name&&!sku)continue;
    ensureStockProduct({sku,name:name||sku,brand:firstStockValue(r,['brand']),category:firstStockValue(r,['category','productcategory','type']),onHand:firstStockValue(r,['onhand','stockonhand','inventory','quantityonhand','stock']),reorderPoint:firstStockValue(r,['reorderpoint','minimumstock','minstock']),cost:firstStockValue(r,['averagecost','costprice','cost']),retailPrice:firstStockValue(r,['retailprice','sellprice','price'])});changed++;
  }
  await save();renderPointCookStock();toast(`${changed} Point Cook products updated`);
}
async function importPointCookMovements(file,type){
  const rows=await readStockFileRows(file);let added=0;
  for(const r of rows){
    const outlet=String(firstStockValue(r,['outlet','location','store'])||'');if(outlet&&!/point\s*cook/i.test(outlet))continue;
    const name=String(firstStockValue(r,['productname','product','name','description'])||'').trim();const sku=String(firstStockValue(r,['sku','productcode','code','barcode'])||'').trim();if(!name&&!sku)continue;
    const p=ensureStockProduct({sku,name:name||sku,brand:firstStockValue(r,['brand']),category:firstStockValue(r,['category','productcategory','type']),cost:firstStockValue(r,['unitcost','costprice','cost']),retailPrice:firstStockValue(r,['unitprice','sellprice','retailprice','price'])});
    const quantity=Math.abs(stockNumber(firstStockValue(r,['quantity','qty','units','items','soldqty','receivedqty'])));if(!quantity)continue;
    const unit=stockNumber(firstStockValue(r,type==='sale'?['unitprice','sellprice','price']:['unitcost','costprice','cost']));const total=stockNumber(firstStockValue(r,['total','totalamount','amount','salesvalue','costtotal']))||quantity*unit;
    const m={type,date:stockDate(firstStockValue(r,['date','createddate','saledate','receiveddate','transactiondate'])),sku:p.sku,name:p.name,category:p.category,quantity,total,unitValue:unit,sourceFile:file.name};
    if(addStockMovement(m))added++;
  }
  await save();renderPointCookStock();toast(`${added} ${type==='sale'?'sales':'purchase'} rows imported`);
}
function pointCookProductMetrics(){
  const moves=state.stockMovements||[],products=state.stockProducts||[];
  return products.map(p=>{const pm=moves.filter(m=>normaliseKey(m.sku||m.name)===normaliseKey(p.sku||p.name));const purchased=pm.filter(m=>m.type==='purchase').reduce((s,m)=>s+Number(m.quantity||0),0),sold=pm.filter(m=>m.type==='sale').reduce((s,m)=>s+Number(m.quantity||0),0);const hasExplicit=Number.isFinite(Number(p.onHand))&&p.lastUpdated;const onHand=hasExplicit?Number(p.onHand||0):Math.max(0,purchased-sold);const salesValue=pm.filter(m=>m.type==='sale').reduce((s,m)=>s+Number(m.total||0),0);const purchaseValue=pm.filter(m=>m.type==='purchase').reduce((s,m)=>s+Number(m.total||0),0);return {...p,purchased,sold,onHand,salesValue,purchaseValue,category:p.category||inferStockCategory(p.name)}});
}
function pointCookFilteredProducts(){const q=($('stockSearch')?.value||'').toLowerCase().trim(),cat=$('stockCategoryFilter')?.value||'All categories',status=$('stockStatusFilter')?.value||'All stock';return pointCookProductMetrics().filter(p=>(cat==='All categories'||p.category===cat)&&(!q||`${p.name} ${p.sku} ${p.brand}`.toLowerCase().includes(q))&&(status==='All stock'||(status==='Low stock'&&p.onHand>0&&p.onHand<=Number(p.reorderPoint||3))||(status==='Out of stock'&&p.onHand<=0)||(status==='In stock'&&p.onHand>Number(p.reorderPoint||3)))).sort((a,b)=>b.sold-a.sold||a.name.localeCompare(b.name))}
function renderPointCookStock(){
  if(!$('pointCookStockBody'))return;state.stockProducts=state.stockProducts||[];state.stockMovements=state.stockMovements||[];
  const products=pointCookProductMetrics(),filtered=pointCookFilteredProducts(),moves=state.stockMovements||[];
  const sales=moves.filter(m=>m.type==='sale'),purchases=moves.filter(m=>m.type==='purchase');
  $('pcSkuCount').textContent=products.length.toLocaleString();$('pcUnitsStock').textContent=products.reduce((s,p)=>s+Number(p.onHand||0),0).toLocaleString();$('pcUnitsSold').textContent=sales.reduce((s,m)=>s+Number(m.quantity||0),0).toLocaleString();$('pcPurchaseUnits').textContent=purchases.reduce((s,m)=>s+Number(m.quantity||0),0).toLocaleString();
  const cats=[...new Set([...STOCK_CATEGORIES,...products.map(p=>p.category).filter(Boolean)])];const old=$('stockCategoryFilter').value;$('stockCategoryFilter').innerHTML=['All categories',...cats].map(x=>`<option>${esc(x)}</option>`).join('');if(cats.includes(old))$('stockCategoryFilter').value=old;
  $('pointCookStockBody').innerHTML=filtered.length?filtered.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><small class="muted">${esc(p.sku||'No SKU')}</small></td><td>${esc(p.brand||'—')}</td><td><span class="pill">${esc(p.category)}</span></td><td>${p.purchased.toLocaleString()}</td><td>${p.sold.toLocaleString()}</td><td><strong>${p.onHand.toLocaleString()}</strong></td><td>${money(p.salesValue)}</td><td>${p.onHand<=0?'<span class="status-pill status-unpaid">Out</span>':p.onHand<=Number(p.reorderPoint||3)?'<span class="status-pill status-due">Low</span>':'<span class="status-pill status-paid">OK</span>'}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">Upload Point Cook product/stock, sales and purchase files to start tracking products.</td></tr>';
  const group=new Map();for(const p of products){const c=p.category||'Other';if(!group.has(c))group.set(c,{category:c,skus:0,stock:0,sold:0,purchased:0,salesValue:0});const g=group.get(c);g.skus++;g.stock+=p.onHand;g.sold+=p.sold;g.purchased+=p.purchased;g.salesValue+=p.salesValue}
  const categoryRows=[...group.values()].sort((a,b)=>b.sold-a.sold);$('pointCookCategoryBody').innerHTML=categoryRows.length?categoryRows.map(g=>`<tr><td><strong>${esc(g.category)}</strong></td><td>${g.skus}</td><td>${g.purchased.toLocaleString()}</td><td>${g.sold.toLocaleString()}</td><td>${g.stock.toLocaleString()}</td><td>${money(g.salesValue)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No category data yet.</td></tr>';
  const top=[...products].sort((a,b)=>b.sold-a.sold).slice(0,10);$('pointCookTopSellers').innerHTML=top.length?top.map((p,i)=>`<div class="stock-rank"><span>${i+1}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${p.sold} sold · ${p.onHand} in stock</small></div></div>`).join(''):'<p class="muted">Import sales to see top sellers.</p>';
}
function exportPointCookStock(){csvDownload(`point-cook-stock-${dateKey(new Date())}.csv`,[['SKU','Product','Brand','Category','Purchased units','Sold units','On hand','Sales value'],...pointCookFilteredProducts().map(p=>[p.sku,p.name,p.brand,p.category,p.purchased,p.sold,p.onHand,p.salesValue.toFixed(2)])])}
window.addEventListener('DOMContentLoaded',()=>{
  const bind=(btn,input,handler)=>{if(!$(btn)||!$(input))return;$(btn).onclick=()=>$(input).click();$(input).onchange=async e=>{const f=e.target.files?.[0];if(f){try{await handler(f)}catch(err){console.error(err);toast(`Import failed: ${err.message}`)}}e.target.value=''}};
  bind('uploadStockProductsBtn','stockProductsInput',importPointCookProducts);bind('uploadStockSalesBtn','stockSalesInput',f=>importPointCookMovements(f,'sale'));bind('uploadStockPurchasesBtn','stockPurchasesInput',f=>importPointCookMovements(f,'purchase'));
  if($('stockCategoryFilter'))$('stockCategoryFilter').onchange=renderPointCookStock;if($('stockStatusFilter'))$('stockStatusFilter').onchange=renderPointCookStock;if($('stockSearch'))$('stockSearch').oninput=renderPointCookStock;if($('exportPointCookStockBtn'))$('exportPointCookStockBtn').onclick=exportPointCookStock;
});
